import React, { useState } from 'react';
import type { YearPerson } from '../year_types/YearTypes';
import { addToOrder } from '../year_api/YearApi';

export default function YearPersonCard({ person }: { person: YearPerson }) {
  // primary: use image from DB (absolute URL normalized in YearApi),
  // fallback: specific historical image by id on static server, then generic default
  const staticById = `http://localhost:9000/images/historyPerson${person.id}.png`;
  const fallback = 'http://localhost:9000/images/default-person.png';
  const src = person.image || staticById || fallback;

  const [isAdding, setIsAdding] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (isAdding) return;
    setIsAdding(true);
    try {
      const resp = await addToOrder(person.id);
      if (resp && resp.ok) {
        // dispatch custom event so parent/listener can update orderInfo without reload
        try { window.dispatchEvent(new CustomEvent('order-updated', { detail: { personId: person.id } })); } catch(_){}
        setIsAdding(false);
        return;
      }
      if (resp && resp.error === 'auth_required') {
        const next = encodeURIComponent(window.location.pathname + window.location.search);
        window.location.href = `/accounts/login/?next=${next}`;
        return;
      }
      alert('Не удалось добавить в заявку');
    } catch (err) {
      console.error(err);
      alert('Ошибка при добавлении в заявку');
    } finally {
      setIsAdding(false);
    }
  }

  return (
    <div className="person-card">
      <div className="card-header">
        <div className="person-name">{person.person_name}</div>
        <form method="post" onSubmit={handleSubmit}>
          {/* csrf handled by backend for fetch, form is visual */}
          <button type="submit" className="expand-btn" disabled={isAdding}>{isAdding ? '…' : '+'}</button>
        </form>
      </div>

      <hr />

      <div className="card-image">
        <img src={src} alt={person.person_name} onError={(e)=>{ (e.currentTarget as HTMLImageElement).src = fallback; }} />
      </div>
      <div className="card-years">
        <p>Годы правления</p>
        <p style={{ marginLeft: '10px' }}><strong>{person.year_from} — {person.year_to}</strong></p>
      </div>

      <div className="card-footer">
        <a href={`/person/${person.id}`} className="details-btn">Подробнее →</a>
      </div>
    </div>
  );
}
